// read-aloud/rd-packager.js: the one function the platform calls for the Output packaging options
// "MathCat TTS" and "MathCat Pregen TTS" (decided 2026-10-31). Runs after Pandoc, on single-page
// HTML made with the "MathML" math setting.
//   makeReadAloudPage(html, mode, { onStatus }) -> { html, report }
//     mode 'tts'    : MathJax's drawing + fonts cut to the characters used + the MathCat TTS reader
//                     (MathCAT 0.7.7 travels in the page, English only, ~1.3 MB)
//     mode 'pregen' : the same drawing and fonts + speech and exploring pre-generated by MathCAT 0.7.7
//                     (the platform's mathcat-wasm/) + the MathCat Pregen TTS reader (~50 KB, no engine)
// Both readers: interface + shared machinery + speech source (read-aloud/reader/), put together here.
// The heavy work happens in a hidden helper page (rd-workbench.html), opened once and reused.
import { assembleBlock } from './reader/assemble-block.js';
const here = (p) => new URL(p, import.meta.url).href;
export const READ_ALOUD_MARKER = 'id="atc-rd-script"';   // present in every page this makes
const MODES = ['tts', 'pregen'];
// The reader block is put together at conversion time from read-aloud/reader/ (interface,
// machinery, speech source) and, for MathCat TTS, read-aloud/engine/mathcat-wasm-en/.
// cache 'no-cache': the browser checks with the server each time, as for the platform's other helpers.
const io = {
  text: async (p) => { const r = await fetch(here('./' + p), { cache: 'no-cache' }); if (!r.ok) throw new Error('read-aloud/' + p + ' not found (HTTP ' + r.status + ')'); return r.text(); },
  bytes: async (p) => { const r = await fetch(here('./' + p), { cache: 'no-cache' }); if (!r.ok) throw new Error('read-aloud/' + p + ' not found (HTTP ' + r.status + ')'); return new Uint8Array(await r.arrayBuffer()); }
};

let workbenchPromise = null;
function workbench() {
  if (!workbenchPromise) workbenchPromise = new Promise((resolve, reject) => {
    const frame = document.createElement('iframe');
    frame.hidden = true;
    frame.setAttribute('aria-hidden', 'true');
    frame.title = 'Read-aloud workbench (hidden)';
    frame.src = here('./rd-workbench.html');
    frame.addEventListener('load', async () => {
      try {
        const wb = frame.contentWindow.rdWorkbench;
        if (!wb) throw new Error('rd-workbench.html did not start');
        await wb.ready;
        resolve(wb);
      } catch (e) { reject(e); }
    }, { once: true });
    frame.addEventListener('error', () => reject(new Error('rd-workbench.html could not be loaded')), { once: true });
    document.body.appendChild(frame);
  }).catch((e) => { workbenchPromise = null; throw e; });
  return workbenchPromise;
}

function beforeBodyEnd(html, text) {
  const at = html.toLowerCase().lastIndexOf('</body>');
  return at < 0 ? html + text : html.slice(0, at) + text + '\n' + html.slice(at);
}

export async function makeReadAloudPage(html, mode, { onStatus } = {}) {
  if (!MODES.includes(mode)) throw new Error('unknown read-aloud mode: ' + mode);
  if (html.includes(READ_ALOUD_MARKER)) throw new Error('this page already has a read-aloud reader');
  if (/<script[^>]+mathjax/i.test(html) || /<mjx-container/i.test(html)) throw new Error('this page uses MathJax; choose the "MathML" math setting');
  const say = (t) => { try { onStatus && onStatus(t); } catch { /* optional */ } };
  const t0 = performance.now();
  say('Starting the read-aloud tools…');
  const wb = await workbench();
  say('Drawing the math with MathJax and cutting its fonts…');
  const drawn = await wb.drawMath(html);
  let page = drawn.html;
  const report = { mode, formulas: drawn.formulas, fonts: drawn.fonts, fontKB: +(drawn.fontBytes / 1024).toFixed(1) };
  let mathcatVersion;
  if (mode === 'pregen') {
    say('Pre-generating the speech with MathCAT…');
    const pre = await wb.pregenerate(page);
    page = pre.html;
    mathcatVersion = pre.mathcatVersion;
    Object.assign(report, { positions: pre.stats.positions, replays: pre.stats.replays, restarts: pre.stats.restarts, failed: pre.stats.failed, speechKB: +(pre.stats.speechBytes / 1024).toFixed(1) });
  }
  const block = await assembleBlock(mode, io, { mathcatVersion });
  page = beforeBodyEnd(page, block.html);
  report.interface = block.info.interface;
  report.mathcat = block.info.mathcatVersion;
  report.pageKB = +(new Blob([page]).size / 1024).toFixed(0);
  report.seconds = +((performance.now() - t0) / 1000).toFixed(1);
  return { html: page, report };
}
